// wing (cross-gables meet in valleys), mansard and gambrel = two pitches, dutch gable = hip below a set-back gablet,
// shed = one slope. One rasterizer turns heights (in half blocks) into blocks: slabs for half steps, stairs facing
// uphill (outer_* on hips, inner_* in valleys), full blocks to close steep faces, ridge blocks where slopes meet.
// Stairs `facing` = the side of the full-height back (uphill); outer_left / inner_left = the extra quarter on the
// counter-clockwise side of `facing` seen from above (same convention as shapes-massing.mjs).
import { functionalCells } from "./check.mjs";
import { colourOf, toneDistance, visible } from "./families.mjs";
import { textureOf, ROOF_PALETTES } from "./roof-texture.mjs";
import { reviewRoof, ratioCap } from "./roof-review.mjs";
