import { upturn } from "./roof-eaves.mjs";
import { applyPresets } from "./roof-presets.mjs";

export const FORM_STYLES = ["cone", "dome", "onion", "tiered", "sawtooth"];          // built by roof-forms.mjs
export const ROOF_STYLES = ["gable", "hip", "pyramid", "mansard", "gambrel", "flat-parapet", "shed", "dutch-gable", ...FORM_STYLES];
export const PITCHES = { half: 0.5, 45: 1, steep: 2, "very-steep": 3 };
const CARD = ["north", "south", "east", "west"];
const DIR = { north: [0, -1], south: [0, 1], west: [-1, 0], east: [1, 0] };
