/** Mutate the roofs.mjs preset table: old presets get palettes, new presets are added (an old name is never replaced). */
export function applyPresets(table) {
  for (const [name, palette] of Object.entries(PALETTE_FOR)) {
    const orig = table[name];
    if (orig) table[name] = (P) => ({ ...orig(P), material: palette });
  }
  for (const [name, fn] of Object.entries(NEW_PRESETS)) if (!table[name]) table[name] = fn;
  return table;
}

